let payload = $json.body ? $json.body : $json;

let mode = "single";
let users = [];
let firstUser = "";

/* ONLY CURRENT INPUT CHECK */
const isTelegram =
  payload.message &&
  typeof payload.message.text === "string";

const source = isTelegram ? "telegram" : "webhook";

/* Telegram input */
if (isTelegram) {
  const text = payload.message.text.trim();

  if (text.startsWith("/compare")) {
    mode = "compare";
    users = text
      .replace("/compare", "")
      .split(",")
      .map(x => x.trim())
      .filter(Boolean);

  } else {
    mode = "single";
    users = [
      text.replace("/analyze", "").trim()
    ];
  }

} else {
  /* Website webhook input */
  mode = payload.mode || "single";
  users = payload.users || [payload.username];
}

firstUser = users[0] || "";

return [{
  json: {
    users,
    count: users.length,
    mode,
    firstUser,
    username: firstUser,
    source
  }
}];

const repos = $input.all().map(item => item.json);

return [{
  json: {
    repoSummary: repos.map(repo =>
      `${repo.name} | Stars: ${repo.stargazers_count} | Language: ${repo.language} | Description: ${repo.description || 'No description'} | Topics: ${(repo.topics || []).join(', ')} | Forks: ${repo.forks_count} | Updated: ${repo.updated_at}`
    ).join('\n')
  }
}];

const allProfiles = $('HTTP Request').all();
const allRepos = $('HTTP Request1').all();

const results = allProfiles.map(profileItem => {
  const profile = profileItem.json;
  const repos = allRepos
    .filter(r => r.json.owner && r.json.owner.login === profile.login)
    .map(r => r.json);

  // PROFILE STRENGTH /20
  let profileStrength = 0;
  if (profile.bio && profile.bio.length > 20) profileStrength += 5;
  if (profile.avatar_url) profileStrength += 3;
  if (profile.blog || profile.twitter_username) profileStrength += 4;
  if (profile.public_repos >= 10) profileStrength += 4;
  if (profile.followers >= 10) profileStrength += 4;

  // REPO QUALITY /30
  let repoQuality = 0;
  const withMeaningfulDesc = repos.filter(r =>
    r.description && r.description.length > 40
  ).length;
  repoQuality += Math.min(withMeaningfulDesc * 1.5, 10);
  const withTopics = repos.filter(r =>
    r.topics && r.topics.length >= 3
  ).length;
  repoQuality += Math.min(withTopics * 2, 10);
  const withStars = repos.filter(r => r.stargazers_count > 0).length;
  repoQuality += Math.min(withStars * 2, 10);

  // TECH DEPTH /20
  let techDepth = 0;
  const languages = [...new Set(repos.map(r => r.language).filter(Boolean))];
  techDepth += Math.min(languages.length * 2, 10);
  const allTopics = repos.flatMap(r => r.topics || []);
  const uniqueTopics = [...new Set(allTopics)];
  techDepth += Math.min(uniqueTopics.length * 0.5, 10);

  // ACTIVITY /20
  let activity = 0;
  const recentRepos = repos.filter(r => {
    const updated = new Date(r.updated_at);
    const now = new Date();
    const diffDays = (now - updated) / (1000 * 60 * 60 * 24);
    return diffDays <= 90;
  }).length;
  activity += Math.min(recentRepos * 3, 15);
  if (profile.public_repos >= 15) activity += 5;

  // SOCIAL PROOF /10
  let socialProof = 0;
  const totalStars = repos.reduce((sum, r) => sum + r.stargazers_count, 0);
  const totalForks = repos.reduce((sum, r) => sum + r.forks_count, 0);
  socialProof += Math.min(totalStars * 0.5, 5);
  socialProof += Math.min(profile.followers * 0.3, 3);
  socialProof += Math.min(totalForks * 0.5, 2);

  const total = profileStrength + repoQuality + techDepth + activity + socialProof;
  const finalScore = (total / 10).toFixed(1);

  // PINNED REPOS from Merge node
  let topRepos = [];
  try {
    const allInputs = $input.all();
    const pinnedItem = allInputs.find(i => i.json.data);
    const pinnedData = pinnedItem.json;
    topRepos = pinnedData.data.user.pinnedItems.nodes.map(repo => ({
      name: repo.name,
      description: repo.description || 'No description',
      language: repo.primaryLanguage?.name || 'Unknown',
      stars: repo.stargazerCount,
      forks: 0,
      topics: repo.repositoryTopics.nodes.map(t => t.topic.name)
    }));
  } catch(e) {
    topRepos = repos
      .sort((a, b) => {
        const scoreA = (a.stargazers_count * 2) + (a.description ? 3 : 0) + ((a.topics?.length || 0) * 2);
        const scoreB = (b.stargazers_count * 2) + (b.description ? 3 : 0) + ((b.topics?.length || 0) * 2);
        return scoreB - scoreA;
      })
      .slice(0, 5)
      .map(r => ({
        name: r.name,
        description: r.description || 'No description',
        language: r.language || 'Unknown',
        stars: r.stargazers_count,
        forks: r.forks_count,
        topics: r.topics || []
      }));
  }

  return {
    json: {
      username: profile.login,
      name: profile.name || 'Not provided',
      bio: profile.bio || 'No bio',
      avatar_url: profile.avatar_url,
      followers: profile.followers,
      public_repos: profile.public_repos,
      languages_detected: languages,
      top_repos: topRepos,
      finalScore,
      profileStrength,
      repoQuality,
      techDepth,
      activity,
      socialProof,
      total
    }
  };
});

return results;

const msg = $('AI Agent').first().json.choices[0].message.content;

const clean = msg
  .replace(/\\n/g, '\n')    // \\n → actual newline
  .replace(/\\"/g, '"')     // \" → "
  .replace(/\\\\/g, '\\')   // \\ → \
  .trim();

return [
  {
    json: {
      text: clean
    }
  }
];

const rawUsers = $json.users || [];

const cleanUsers = rawUsers.map(u =>
  u.replace('/analyze', '')
   .replace('/compare', '')
   .trim()
).filter(Boolean);

return [
{
json: {
users: cleanUsers,
count: cleanUsers.length
}
}
];

const users = $json.users || [];

return users.map(username => ({
  json: {
    username: username.trim()
  }
}));

const allItems = $input.all();
const isCompare = allItems.length > 1;
let prompt;

if (isCompare) {
  const candidatesData = allItems.map(i => i.json);
  prompt = "You are a senior technical recruiter and software engineering expert with 15+ years of hiring experience at top-tier tech companies. You have been given GitHub profile data of multiple candidates with pre-computed scoring metrics. Your job is to rank them and provide actionable hiring intelligence. SCORING SYSTEM: Profile Strength /20 (bio, avatar, website, social presence), Repo Quality /30 (project complexity, documentation, real-world utility), Tech Depth /20 (language diversity, framework usage, architecture patterns), Activity /20 (commit frequency, contribution consistency, recent activity), Social Proof /10 (stars, forks, followers, community recognition), Total /100 converted to /10. CRITICAL EVALUATION RULES: DO NOT rank candidates higher based on repo names containing buzzwords like 'AI', 'ML', 'prediction', 'classification', 'blockchain', 'GPT' alone. INSTEAD evaluate: Does the description explain a real problem being solved? Are there actual frameworks in topics suggesting real implementation? Pinned repos are candidate's self-highlighted best work — prioritize them. A repo named 'Disease-Outbreak-Prediction' with no topics and vague description is NOT impressive. A repo named 'ksolves-resolveai' with description explaining semantic routing, LLM fallback, audit logs and 10+ relevant topics IS impressive. Be fair, not harsh — reward genuine effort and real problem-solving, penalize buzzword-stuffing not beginners. CANDIDATES DATA: " + JSON.stringify(candidatesData) + " Analyze each candidate deeply and return in STRICT format: 🏆 GITHUB CANDIDATE COMPARISON REPORT. 🥇 RANK 1: [username] - [score]/10. Strengths: [2-3 specific technical strengths based on actual project data]. Why #1: [specific reason with data points from their pinned repos and real projects]. 🥈 RANK 2: [username] - [score]/10. Strengths: [2-3 specific technical strengths]. Why below Rank 1: [specific gap or weakness compared to rank 1 based on real project depth]. 🥉 RANK 3: [username] - [score]/10 (if exists). Strengths: [2-3 specific technical strengths]. Why below Rank 2: [specific gap]. 📊 METRIC-BY-METRIC BREAKDOWN: Profile Strength: [rank candidates]. Repo Quality: [rank candidates]. Tech Depth: [rank candidates]. Activity: [rank candidates]. Social Proof: [rank candidates]. 📌 ROLE-BASED RECOMMENDATION: Best For Startup: [username] - [one line reason based on actual projects]. Best For Corporate: [username] - [one line reason]. Best For Internship: [username] - [one line reason]. Best For AI/ML Teams: [username] - [one line reason]. Best For Frontend Role: [username] - [one line reason]. 💼 FINAL HIRING VERDICT: [2-3 lines on who to hire first, why, and what to watch out for based on real project analysis].";
} else {
  const data = allItems[0].json;
  prompt = "You are a senior technical recruiter and software engineering expert with 15+ years of hiring experience at top-tier tech companies like Google, Meta, and Microsoft. You have been given a GitHub profile with pre-computed scoring metrics. Your job is to produce a professional, data-driven hiring assessment. SCORING SYSTEM: Profile Strength /20 (bio, avatar, website, social presence), Repo Quality /30 (project complexity, documentation, real-world utility), Tech Depth /20 (language diversity, framework usage, architecture patterns), Activity /20 (commit frequency, contribution consistency, recent activity), Social Proof /10 (stars, forks, followers, community recognition), Total /100 converted to /10. CRITICAL EVALUATION RULES: DO NOT praise or highlight repos based on names containing buzzwords like 'AI', 'ML', 'prediction', 'classification', 'blockchain', 'GPT', 'neural network' alone — these mean nothing without real implementation evidence. INSTEAD evaluate: Does the description explain a real problem being solved? Are there actual frameworks in topics that suggest real implementation? Does the project name and description align or is it just buzzwords? A repo named 'Disease-Outbreak-Prediction' with no topics and vague description is NOT a strong project. A repo named 'ksolves-resolveai' with description explaining semantic routing, LLM fallback, audit logs, human escalation and 10+ relevant topics IS a strong project — because it describes a real system solving a real enterprise problem. Pinned repos are the candidate's self-highlighted best work — always prioritize them in your strongest projects section. Be fair, not harsh. Reward genuine effort, learning trajectory, and real problem-solving. Penalize buzzword-stuffing and fake depth, not beginners. A 10/10 is reserved for production-grade projects with real users. 7-8/10 means genuinely strong developer. 5-6/10 is average with effort but lacks depth. CANDIDATE DATA: " + JSON.stringify(data) + " Produce a professional hiring report in STRICT format: 🔥 GITSCAN PRO REPORT: @[username]. ⭐ OVERALL SCORE: [finalScore]/10. 📊 SCORE BREAKDOWN: Profile Strength: [profileStrength]/20. Repo Quality: [repoQuality]/30. Tech Depth: [techDepth]/20. Activity: [activity]/20. Social Proof: [socialProof]/10. 🛠 TOP SKILLS DETECTED: [List 4-6 specific technologies detected from actual repo topics and languages — not assumed from names]. 🚀 WHAT STANDS OUT: [2-3 sentences on what makes this candidate genuinely interesting — mention actual pinned project names and what real problem they solve]. 📌 STRONGEST PROJECTS: 1. [pinned repo name] - [what real problem it solves and what engineering complexity it demonstrates]. 2. [repo name] - [one line on real implementation]. 3. [repo name] - [one line]. ⚠️ AREAS TO IMPROVE: 1. [specific actionable improvement based on actual gaps in their profile]. 2. [specific actionable improvement]. 🎯 BEST FIT ROLES: [List 2-3 specific roles this person is genuinely best suited for based on their actual projects]. 💼 HIRING RECOMMENDATION: Level: [Intern/Junior/Mid-Level/Senior]. Decision: [Hire/Strong Hire/Hold/Pass]. Reason: [2-3 sentences with specific data-backed reasoning from their actual pinned projects and scores]. 📝 VERDICT: [One powerful closing sentence summarizing candidate's real potential].";
}

const result = {
  model: "llama-3.3-70b-versatile",
  max_tokens: 1024,
  messages: [
    {
      role: "user",
      content: prompt
    }
  ]
};

return [{ json: result }];

