={
  "query": "{ user(login: \"{{ $json.login }}\") { pinnedItems(first: 6, types: REPOSITORY) { nodes { ... on Repository { name description stargazerCount primaryLanguage { name } repositoryTopics(first: 5) { nodes { topic { name } } } } } } } }"
}
